"""Generate the manual SQL Editor setup from the ordered migration files."""
from pathlib import Path

root = Path(__file__).resolve().parents[1]
parts = [
    '-- CV & Portfolio Builder: manual Supabase SQL Editor setup.\n'
    '-- Generated by: python tools/build_supabase_setup.py\n'
    '-- Creates/updates the application tables, RLS, RPCs and private bucket.\n'
    '-- Run the WHOLE file in the intended project, as the postgres role.\n'
    '-- This does not deploy the share-media Edge Function or configure OAuth.\n'
    '-- SQL Editor execution does not record CLI migration history.\n'
    'begin;\n'
]
for migration in sorted((root / 'supabase/migrations').glob('*.sql')):
    parts.append(f'\n-- ===== {migration.name} =====\n')
    parts.append(migration.read_text(encoding='utf-8').rstrip() + '\n')
parts.append("\nnotify pgrst, 'reload schema';\ncommit;\n\n"
             "select 'Setup complete' as status, count(*) as application_tables\n"
             "from information_schema.tables\n"
             "where table_schema = 'public'\n"
             "  and table_name in ('profiles', 'documents', 'document_shares', 'cv_builder_drafts');\n")
target = root / 'supabase/setup.sql'
target.write_text(''.join(parts), encoding='utf-8')
print(f'Generated {target.relative_to(root)}')
